              <span class="" id="bookingHourPrice">350 ฿</span>
            </div>
            <div class="flex justify-between text-xs text-stone-400">
              <span class="">ค่าเป้าธนูมาตรฐาน</span>
              <span class="" id="bookingTargetPrice">20 ฿</span>
